insert into public.products (id, brand, name, colorway, type, price, mrp, year, is_new, rating, reviews, blurb, details, spin_frames, sort_order)
values
('dunk-low-university-red', 'Nike', 'Dunk Low', 'University Red', 'Low-top', 12795, 14995, 2020, true, 4.9, 1284, 'White leather base, red overlays, red laces. The college-colours Dunk that started as a 1985 basketball shoe.', array['Full-grain leather upper', 'Perforated toe box', 'Embroidered NIKE heel tab', 'Rubber cupsole with pivot-circle tread']::text[], 18, 0),
('jordan-1-high-chicago', 'Jordan', 'Air Jordan 1 High OG', 'Chicago Lost & Found', 'High-top', 38995, 42995, 2022, true, 4.9, 962, 'The 1985 Chicago colourway, aged on purpose: cracked black collar, sail midsole, slightly off-white panels.', array['Leather upper with cracked-finish collar', 'Nike Air tongue label', 'Encapsulated Air in the heel', 'Sail rubber cupsole']::text[], 18, 1),
('jordan-4-fire-red', 'Jordan', 'Air Jordan 4 Retro', 'Fire Red', 'High-top', 32495, 34995, 2020, false, 4.8, 731, 'White leather, black wings, red hits and Nike Air on the heel, just as the 1989 pair had it.', array['Leather upper with mesh netting', 'Moulded lace wings', 'Visible Air unit in the heel', 'Nike Air heel branding']::text[], 18, 2),
('jordan-1-low-gym-red', 'Jordan', 'Air Jordan 1 Low', 'Gym Red', 'Low-top', 10795, 11495, 2021, false, 4.7, 418, 'The Jordan 1 cut below the ankle, in two-tone gym red over white.', array['Leather upper', 'Stitched Wings logo on the heel', 'Encapsulated Air in the heel', 'Rubber cupsole']::text[], 18, 3),
('jordan-11-cherry', 'Jordan', 'Air Jordan 11 Retro', 'Cherry', 'High-top', 29995, 31995, 2022, true, 4.8, 655, 'Glossy red patent leather wrapped around a white upper, sitting on an icy translucent sole.', array['Patent leather mudguard', 'Ballistic mesh upper', 'Carbon-fibre shank plate', 'Translucent rubber outsole']::text[], 18, 4),
('dunk-low-panda', 'Nike', 'Dunk Low Retro', 'White Black', 'Low-top', 9695, 9695, 2021, false, 4.7, 3120, 'Black overlays on white leather. The pair most people mean when they say "Panda".', array['Leather upper', 'Perforated toe box', 'Padded low-cut collar', 'Rubber cupsole with pivot-circle tread']::text[], 18, 5),
('air-force-1-university-red', 'Nike', 'Air Force 1 Low', 'White University Red', 'Low-top', 9995, 10795, 2020, false, 4.6, 540, 'An all-white Air Force 1 with a red sole, red collar lining and red AIR on the midsole.', array['Leather upper', 'Perforated toe box', 'Nike Air cushioning', 'Rubber cupsole with pivot circles']::text[], 18, 6),
('air-max-90-infrared', 'Nike', 'Air Max 90', 'Infrared', 'Runner', 13995, 14995, 2020, false, 4.8, 889, 'The 1990 original colourway. Grey and black panels built to point at the glowing Air window.', array['Mesh upper with leather and synthetic overlays', 'Visible Max Air unit', 'Padded collar', 'Waffle rubber outsole']::text[], 18, 7),
('dunk-high-university-red', 'Nike', 'Dunk High', 'University Red', 'High-top', 11895, 12795, 2021, false, 4.7, 367, 'The same red and white blocking as the Low, with the full padded collar.', array['Leather upper', 'Padded high-cut collar', 'Perforated toe box', 'Rubber cupsole with pivot-circle tread']::text[], 18, 8),
('samba-og-scarlet', 'adidas', 'Samba OG', 'White Better Scarlet', 'Low-top', 10999, 10999, 2023, true, 4.8, 1502, 'The indoor football trainer from 1949, with scarlet stripes and a dark gum sole.', array['Leather upper', 'Suede T-toe overlay', 'Serrated three stripes', 'Gum rubber outsole']::text[], 18, 9),
('campus-00s-scarlet', 'adidas', 'Campus 00s', 'Better Scarlet', 'Low-top', 10999, 11999, 2023, true, 4.6, 478, 'A wider, chunkier Campus in all-over scarlet suede with off-white stripes.', array['Suede upper', 'Padded tongue and collar', 'Leather three stripes', 'Rubber cupsole']::text[], 18, 10),
('gazelle-scarlet', 'adidas', 'Gazelle Indoor', 'Scarlet', 'Low-top', 11999, 11999, 2023, false, 4.7, 391, 'Deep red suede over a see-through gum sole, taken from the 1979 indoor trainer.', array['Suede upper', 'Leather three stripes and heel tab', 'Gold foil Gazelle lettering', 'Translucent gum rubber outsole']::text[], 18, 11),
('nb-550-white-red', 'New Balance', '550', 'White Red', 'Low-top', 12999, 13999, 2021, false, 4.6, 712, 'A 1989 basketball low brought back unchanged: white leather, red N, black and red sole.', array['Leather upper', 'Perforated side panels', 'Padded collar', 'Rubber cupsole']::text[], 18, 12),
('chuck-70-enamel-red', 'Converse', 'Chuck 70 Hi', 'Enamel Red', 'High-top', 6499, 6999, 2019, false, 4.7, 1043, 'Heavier canvas, a taller glossy foxing stripe and the black heel plate of the 1970s Chuck.', array['12oz canvas upper', 'Cushioned OrthoLite insole', 'Egret rubber toe cap and foxing', 'Vulcanised rubber sole']::text[], 18, 13),
('old-skool-black-white', 'Vans', 'Old Skool', 'Black White', 'Low-top', 5499, 5499, 2016, false, 4.6, 2210, 'Black suede and canvas with the white side stripe. The first Vans to wear it, in 1977.', array['Suede and canvas upper', 'Reinforced toe cap', 'Padded collar', 'Vulcanised waffle outsole']::text[], 18, 14),
('mexico-66-tricolor', 'Onitsuka Tiger', 'Mexico 66', 'White Blue Red', 'Runner', 10999, 10999, 2018, false, 4.7, 834, 'A thin-soled 1966 trainer in white leather with blue and red tiger stripes and a heel flap.', array['Leather upper with suede toe and heel', 'Tiger stripes on both sides', 'Heel tab with cross-stitch', 'Low-profile rubber outsole']::text[], 18, 15)
